import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Memory tools","description":"","frontmatter":{},"headers":[],"relativePath":"memory/tools.md","filePath":"memory/tools.md","lastUpdated":1793126588000}'),c={name:"memory/tools.md"};function a(i,e,n,s,l,m){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="memory-tools" tabindex="-1">Memory tools <a class="header-anchor" href="#memory-tools" aria-label="Permalink to &quot;Memory tools&quot;">​</a></h1><p>Every delivery method uses these names, strict inputs, and Zod-derived outputs.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Exact input</th><th>Exact output</th></tr></thead><tbody><tr><td><code>memory_store</code></td><td><code>memory_type</code>, <code>record_type</code>, <code>summary</code>, <code>source</code>, <code>created_by</code>, and <code>confidence</code>; optional <code>topic</code>, <code>details</code>, and <code>tags</code></td><td>stored record with generated ULID</td></tr><tr><td><code>memory_supersede</code></td><td>every <code>memory_store</code> field plus the active <code>target_id</code></td><td>replacement record</td></tr><tr><td><code>memory_delete</code></td><td><code>target_id</code>, <code>reason</code>, <code>source</code>, and <code>created_by</code></td><td>tombstone</td></tr><tr><td><code>memory_get</code></td><td>Crockford ULID <code>id</code></td><td>record or tombstone</td></tr><tr><td><code>memory_list</code></td><td>optional <code>topic</code>, <code>memory_type</code>, <code>limit</code> of 1-100, and <code>include_superseded</code></td><td>records newest first</td></tr><tr><td><code>memory_search</code></td><td><code>query</code>; optional <code>topic</code>, <code>memory_type</code>, <code>limit</code> of 1-100, <code>include_superseded</code>, and <code>max_chars</code> of 256-100000</td><td>BM25-ranked records</td></tr><tr><td><code>memory_validate</code></td><td><code>{}</code></td><td>validation and cache report</td></tr><tr><td><code>memory_export</code></td><td><code>{}</code></td><td>JSONL string</td></tr><tr><td><code>memory_import</code></td><td>JSONL <code>content</code>; optional <code>preview</code> (defaults to <code>true</code>)</td><td>import report</td></tr></tbody></table><p>Store and supersede accept these type pairs: <code>semantic</code> with <code>fact</code>, <code>episodic</code> with <code>decision</code> or <code>event</code>, and <code>procedural</code> with <code>lesson</code>. Source has <code>kind: artifact | user-confirmed | discussion | tool-observation</code>, nullable <code>ref</code>, and nullable <code>revision</code>. Confidence is <code>confirmed | verified</code>. Tags must be unique. Summary is nonblank and at most 240 Unicode code points. Details is at most 2000 Unicode code points and 12 nonempty lines. Delete reasons are nonblank and at most 1000 characters.</p><p>Search queries are limited to 16 KiB of UTF-8 and import/export content to 64 MiB. A validation report contains <code>valid</code>, record and tombstone counts, errors, and cache outcome/evidence. Import reports contain <code>valid</code>, record and tombstone counts, errors, and optional warnings.</p><p><code>memory_import</code> is preview-only when <code>preview</code> is omitted. Inspect <code>valid</code> and <code>errors</code>, then call with <code>preview: false</code> to publish. Prefer supersession to deletion when the old fact has historical value. Set the source kind honestly. Use <code>verified</code> only for artifact or tool evidence.</p><p>The library throws <code>MemoryError</code> subclasses for configuration, conflicts, locks, secrets, and schema failures. Tool hosts return those failures in their transport-specific error form. Common failures include an invalid ULID or enum, oversized text, duplicate tags, a suspected secret, a disabled shard, cache policy, or a configured storage limit.</p><h2 id="cancellation" tabindex="-1">Cancellation <a class="header-anchor" href="#cancellation" aria-label="Permalink to &quot;Cancellation&quot;">​</a></h2><p>Every host forwards its request cancellation signal into Memory: the pi extension reads the tool call <code>AbortSignal</code>, the OpenCode plugin reads the invocation <code>abort</code>, and the MCP server passes the request handler <code>signal</code>. The direct library accepts an optional <code>MemoryOperationControl</code> (<code>{ signal, deadline }</code>) on every store operation.</p><p>Guarantees:</p><ul><li>An already-aborted (or past-deadline) call rejects with the stable <code>MemoryCancellationError</code> (<code>code: &#39;ABORTED&#39;</code> or <code>&#39;DEADLINE_EXCEEDED&#39;</code>) <strong>before</strong> any backend, lease, or cache work, so it never mutates canonical state.</li><li>Cancellation is checked at every safe phase boundary: before state reads, before search ranking, before validation, before import parsing and publication, and before cache rebuild starts.</li><li>The atomic publication batch (<code>applyBatch</code>) and the PostgreSQL <code>COMMIT</code> are <strong>non-interruptible commit boundaries</strong>: a check runs immediately before, but never inside. Post-commit disposable-cache maintenance is bounded and also non-interruptible; if cache synchronization fails after publication the error says the canonical mutation committed.</li><li>Cancelling a call that is only waiting for the shard authority lease stops promptly and leaves the FIFO queue healthy for the next caller.</li><li><code>memory_validate</code> surfaces cancellation inside its report (<code>valid: false</code>, cache outcome <code>skipped</code>); every other operation throws. Each transport surfaces the error in its native form: pi and OpenCode propagate the thrown error, MCP returns an <code>isError</code> result with the stable message.</li></ul>',11)])])}const u=o(c,[["render",a]]);export{h as __pageData,u as default};
